        ("ওজনহীনতা কীভাবে সৃষ্টি হয়—ব্যাখ্যা করো।", "মুক্ত পতনের সময় বস্তু ও তার চারপাশ একই ত্বরণে নিচে পড়ে, ফলে বস্তুটি তার支承 পৃষ্ঠে কোনো বল প্রয়োগ করে না। তখন ওজন শূন্য অনুভূত হয়, একে ওজনহীনতা বলে।"),
