        ("আলোকবর্ষ কী? কেন এটি দূরত্বের একক?", "আলো এক বছরে যে দূরত্ব অতিক্রম করে তাকে আলোকবর্ষ বলে। মহাকাশীয় দূরত্ব এত বিশাল যে কিলোমিটারে প্রকাশ করা অসুবিধাজনক, তাই আলোকবর্ষ ব্যবহার করা হয়।"),
        ("মহাবিশ্ব ও ছায়াপথের সম্পর্ক ব্যাখ্যা করো।", "মহাবিশ্ব হলো সমগ্র স্থান ও তার中的所有 বস্তুর সমষ্টি। ছায়াপথ হলো অসংখ্য নক্ষত্র, গ্যাস ও ধুলোর বিশাল সমষ্টি; অসংখ্য ছায়াপথ মিলে মহাবিশ্ব গঠিত।"),
